function identifierHash(string $type,string $value):string{
 global $cfg;
 $secret=(string)($cfg['identity_hmac_key']??'');
 if(strlen($secret)<32||str_contains($secret,'REPLACE_WITH'))throw new RuntimeException('Identity protection secret is not configured.');
 $normalized=strtoupper(preg_replace('/[^A-Za-z0-9]/','',$value));
 if($type==='cnic'&&!preg_match('/^[0-9]{13}$/',$normalized))throw new RuntimeException('CNIC must have 13 digits.');
 if($type!=='cnic'&&(!preg_match('/^[A-Z0-9]{5,25}$/',$normalized)))throw new RuntimeException('Passport / ID number must contain 5–25 letters or digits.');
 return hash_hmac('sha256',$type.':'.$normalized,$secret);
}
function saveIdentityNumbers(int $userId,array $ids):void{
 foreach($ids as $type=>$value){
  $value=trim($value);if($value==='')continue;
  $hash=identifierHash($type,$value);
  $normalized=strtoupper(preg_replace('/[^A-Za-z0-9]/','',$value));
  $masked='••••'.substr($normalized,-4);
  // A number entered as 'National ID' must also be checked against legacy CNIC records.
  // Cross-type comparison prevents a straightforward duplicate under another identity type.
  $checkHashes=[];
  foreach(['cnic','national_id','passport'] as $otherType){
   try{$checkHashes[]=identifierHash($otherType,$value);}catch(RuntimeException $ignored){}
  }
  $placeholders=implode(',',array_fill(0,count($checkHashes),'?'));
  $other=q('SELECT user_id FROM candidate_identifiers WHERE identifier_hash IN ('.$placeholders.') LIMIT 1',$checkHashes)->fetch();
  if($other&&(int)$other['user_id']!==$userId)throw new RuntimeException('This identity number is linked to another account. Contact support for identity review; do not create a second login.');
  $existing=q('SELECT identifier_hash FROM candidate_identifiers WHERE user_id=? AND id_type=?',[$userId,$type])->fetch();
  if($existing&&$existing['identifier_hash']!==$hash)throw new RuntimeException('Identity number changes require authorized verification. Contact support.');
  if(!$existing)q('INSERT INTO candidate_identifiers(user_id,id_type,identifier_hash,masked_value) VALUES(?,?,?,?)',[$userId,$type,$hash,$masked]);
 }
}
function projectPromptFor(array $a):string{
 global $cfg;
 $default=setting('project_default');
 if(empty($cfg['ai_api_key']))return $default;
 try{
  $r=gjwAiJson($cfg,'Return JSON object {"question":string} containing exactly one practical, short, fair two-minute work scenario question for a job applicant. Do not request private personal information or an AI-generated answer. No markdown.','Profession: '.$a['profession'],300);
  $question=trim((string)($r['question']??''));if(strlen($question)<30||strlen($question)>900)throw new RuntimeException('Bad question');return $question;
 }catch(Throwable $e){error_log('GJW project generation unavailable');return $default;}
}
function courseMatches(string $profession,array $data):array{
 $terms=strtolower($profession.' '.($data['skills']??'').' '.($data['experience']??'').' '.($data['job_requirements']??''));
 $courses=q('SELECT id,title,description,provider,url,keywords FROM course_catalog WHERE active=1 ORDER BY id')->fetchAll();
 $matches=[];
 foreach($courses as $course){$score=0;foreach(preg_split('/\s+/',strtolower($course['keywords'])) as $word){if(strlen($word)>2&&str_contains($terms,$word))$score++;}if($score>0){$course['match_score']=$score;$matches[]=$course;}}
 usort($matches,fn($a,$b)=>$b['match_score']<=>$a['match_score']);return array_slice($matches,0,5);
}
function lateFeeDetails(array $a):array{
 $start=strtotime(($a['registration_started_at']??$a['created_at']).' UTC');
 $late=time()>($start+1260);
 $base=(int)$a['fee_pkr'];
 // Only domestic initial fee is doubled; international late fee is configurable separately.
 $extra=$late&&!((int)($a['late_fee_waived']??0))?(strcasecmp($a['country'],'Pakistan')===0?2000:(int)setting('international_late_extra_pkr','0')):0;
 return ['base'=>$base,'extra'=>$extra,'discount'=>approvedCouponDiscount((int)$a['id']),'total'=>max(0,$base+$extra-approvedCouponDiscount((int)$a['id'])),'late'=>$late];
}
function lateGateRequired(array $a):bool{
 if((int)($a['late_fee_waived']??0)===1||!empty($a['result_approved_at']))return false;
 $start=strtotime(($a['registration_started_at']??$a['created_at']).' UTC');
 if(time()<=$start+1260)return false;
 $r=q('SELECT status FROM payments WHERE application_id=? AND kind="assessment"',[$a['id']])->fetch();
 return !$r||$r['status']!=='approved';
}
function lateGateRedirect(array $a):void{
 if(lateGateRequired($a))go('late_gate&id='.(int)$a['id']);
}
function approvedCouponDiscount(int $aid):int{
 $r=q('SELECT discount_pkr FROM coupon_requests WHERE application_id=? AND status="approved" ORDER BY id DESC LIMIT 1',[$aid])->fetch();
 return max(0,(int)($r['discount_pkr']??0));
}
function couponPreviewAmount(array $a):int{
 $base=(int)$a['fee_pkr'];$start=strtotime(($a['registration_started_at']??$a['created_at']).' UTC');
 if(time()>$start+1260&&!(int)($a['late_fee_waived']??0))$base+=strcasecmp($a['country'],'Pakistan')===0?2000:(int)setting('international_late_extra_pkr','0');
 return max(0,$base-approvedCouponDiscount((int)$a['id']));
}
