function fileUpload(int $aid,string $kind,array $f):string{global $cfg;$allowed=['cv'=>['application/pdf'=>'pdf','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','image/jpeg'=>'jpg','image/png'=>'png'],'identity'=>['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'],'payment_receipt'=>['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'],'intro_video'=>['video/webm'=>'webm','video/mp4'=>'mp4','video/quicktime'=>'mov']];if(!isset($allowed[$kind])||($f['error']??1)!==UPLOAD_ERR_OK||!isset($f['tmp_name'])||!is_uploaded_file($f['tmp_name']))throw new RuntimeException('File upload failed. Check upload size.');$max=$kind==='intro_video'?60*1024*1024:8*1024*1024;if($f['size']>$max||$f['size']<1)throw new RuntimeException('File exceeds limit or is empty');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!isset($allowed[$kind][$mime]))throw new RuntimeException('Unsupported file type: '.$mime);$base=rtrim($cfg['storage_dir'],'/');$dir=$base.'/'.$aid;if(!is_dir($dir)&&!@mkdir($dir,0700,true)&&!is_dir($dir))throw new RuntimeException('Storage is not writable');$filename=bin2hex(random_bytes(24)).'.'.$allowed[$kind][$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$filename))throw new RuntimeException('Could not store file');$path=$dir.'/'.$filename;
 try{q('INSERT INTO documents(application_id,kind,original_name,relative_path,mime) VALUES(?,?,?,?,?)',[$aid,$kind,basename($f['name']),$aid.'/'.$filename,$mime]);}
 catch(Throwable $ex){@unlink($path);throw $ex;}
 return $path;
}
function saveAssessmentPayment(int $aid,int $amount,string $reference,array $file):void{
 global $db;
 $path=null;
 $db->beginTransaction();
 try{
  q('SELECT id FROM applications WHERE id=? FOR UPDATE',[$aid])->fetch();
  $existing=q('SELECT status FROM payments WHERE application_id=? AND kind="assessment" FOR UPDATE',[$aid])->fetchColumn();
  if($existing!==false&&$existing!=='rejected')throw new RuntimeException('Payment proof has already been submitted.');
  $path=fileUpload($aid,'payment_receipt',$file);
  q('INSERT INTO payments(application_id,kind,amount_pkr,transfer_reference,status) VALUES(?,"assessment",?,?,"pending") ON DUPLICATE KEY UPDATE amount_pkr=VALUES(amount_pkr),transfer_reference=VALUES(transfer_reference),status="pending",reviewer_id=NULL,reviewed_at=NULL',[$aid,$amount,$reference]);
  q('UPDATE applications SET status="payment_review" WHERE id=?',[$aid]);
  audit('payment_submitted',$aid);
  $db->commit();
 }catch(Throwable $ex){
  if($db->inTransaction()){$db->rollBack();if($path!==null)@unlink($path);}
  throw $ex;
 }
}
