 $pending=q('SELECT cr.*,a.reference,u.name,c.code_hint FROM coupon_requests cr JOIN applications a ON a.id=cr.application_id JOIN users u ON u.id=a.user_id JOIN coupons c ON c.id=cr.coupon_id WHERE cr.status="pending" ORDER BY cr.id DESC LIMIT 100')->fetchAll();
 $html.='<div class="card"><h2>Pending Approvals</h2>';
 foreach($pending as $r)$html.='<div class="card"><b>'.e($r['reference']).'</b> '.e($r['name']).' • code ending '.e($r['code_hint']).' • discount PKR '.(int)$r['discount_pkr'].' • balance PKR '.(int)$r['balance_pkr'].'<form method="post">'.csrf().'<input type="hidden" name="action" value="review"><input type="hidden" name="request_id" value="'.(int)$r['id'].'"><button name="decision" value="approved">Approve</button> <button name="decision" value="rejected" class="secondary">Reject</button></form></div>';
 $html.='</div>';layout('Coupon Management',$html);
}
if($p==='csv'){$u=adminOnly();$rows=q('SELECT a.reference,u.name,u.email,a.profession,a.country,a.status,a.fee_pkr,a.final_score,a.created_at FROM applications a JOIN users u ON u.id=a.user_id ORDER BY a.id DESC')->fetchAll();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="assessment_applications.csv"');$fp=fopen('php://output','w');fputcsv($fp,['Reference','Name','Email','Profession','Country','Status','Fee PKR','Score','Created UTC']);foreach($rows as $row)fputcsv($fp,array_map(fn($v)=>is_string($v)&&preg_match('/^[=+@\-]/',$v)?"'".$v:$v,array_values($row)));fclose($fp);exit;}
